// Unit tests for @ohos/dsh-ptc-runtime-vm.
//
// Run from the PAYLOAD tree (the plugin imports @deepseek-ai/schemastery and
// @deepseek-ai/dsh-ptc-runtime, which only resolve there — same constraint as
// the fs-search plugin tests, see AGENTS.md §8):
//
//   cd .build/payload/profile-ohos/profiles/ohos/node_modules/@ohos/dsh-ptc-runtime-vm
//   node --test test/*.test.mjs            # normal
//   node --jitless --test test/*.test.mjs  # prove the no-WASM path (device parity)

import test from "node:test";
import assert from "node:assert/strict";
import {
	OhosPtcRuntime,
	startRun,
	runInWorker,
	validateBindings,
	clampTimeoutMs,
	jsonViolation,
	normalizeConfig
} from "../index.js";

const CONFIG = { timeoutMs: 5000, maxTimeoutMs: 10000, maxOutputBytes: 65536, maxOldGenerationSizeMb: 64 };

function makeBindings(overrides = {}) {
	return [
		{
			global: "tools",
			functions: {
				echo: async (args) => args,
				boom: async () => {
					throw new Error("kaput");
				},
				stall: () => new Promise(() => {}),
				...overrides
			},
			errorClass: { name: "ToolCallError", memberNameProperty: "toolName" }
		}
	];
}

function specOf(program, bindings = makeBindings(), timeoutMs = CONFIG.timeoutMs) {
	return { program, bindings, timeoutMs };
}

test("plain completion value crosses back", async () => {
	const result = await runInWorker(specOf("return 42"), CONFIG);
	assert.deepEqual(result, { logs: [], value: 42 });
});

test("console output is captured in order", async () => {
	const result = await runInWorker(specOf("console.log('a'); console.log('b', { c: 1 }); return 'done'"), CONFIG);
	assert.deepEqual(result.logs, ["a", "b {\"c\":1}"]);
	assert.equal(result.value, "done");
});

test("value-less run resolves with logs only", async () => {
	const result = await runInWorker(specOf("console.log('side effect only')"), CONFIG);
	assert.deepEqual(result, { logs: ["side effect only"] });
});

test("binding call round-trips and returns the settled value", async () => {
	const result = await runInWorker(specOf("const r = await tools.echo({ a: 1 }); return r.a"), CONFIG);
	assert.deepEqual(result, { logs: [], value: 1 });
});

test("zero-argument binding call arrives as an empty object", async () => {
	const result = await runInWorker(specOf("const r = await tools.echo(); return r"), CONFIG);
	assert.deepEqual(result, { logs: [], value: {} });
});

test("failed binding rejects with the declared error class", async () => {
	const program = `
		try {
			await tools.boom({});
			return 'unreached';
		} catch (error) {
			return { name: error.name, toolName: error.toolName, message: error.message, isInstance: error instanceof ToolCallError };
		}
	`;
	const result = await runInWorker(specOf(program), CONFIG);
	assert.deepEqual(result.value, { name: "ToolCallError", toolName: "boom", message: "kaput", isInstance: true });
});

test("TypeScript annotations are a syntax error (no stripping on this backend)", async () => {
	const result = await runInWorker(specOf("const x: number = 1; return x"), CONFIG);
	assert.equal(result.error?.kind, "exception");
	assert.match(result.error?.message ?? "", /SyntaxError|Unexpected|Expected|Missing initializer/i);
});

test("sync infinite loop is killed by the elapsed budget", async () => {
	const startedAt = Date.now();
	const result = await runInWorker(specOf("for (;;) {}", makeBindings(), 250), CONFIG);
	const elapsed = Date.now() - startedAt;
	assert.equal(result.error?.kind, "timeout");
	assert.ok(elapsed < 5000, `timeout took ${elapsed}ms`);
});

test("abort during a stalled binding settles as abort", async () => {
	const run = startRun(specOf("await tools.stall({}); return 'never'"), CONFIG);
	setTimeout(() => run.abort("user cancelled"), 150);
	const result = await run.result;
	assert.equal(result.error?.kind, "abort");
	assert.match(result.error?.message ?? "", /user cancelled/);
	await run.finished;
});

test("pre-aborted signal settles immediately", async () => {
	const controller = new AbortController();
	controller.abort("nope");
	const result = await runInWorker({ ...specOf("return 1"), signal: controller.signal }, CONFIG);
	assert.equal(result.error?.kind, "abort");
	assert.match(result.error?.message ?? "", /nope/);
});

test("program exception reports kind exception with the message", async () => {
	const result = await runInWorker(specOf("throw new Error('deliberate')"), CONFIG);
	assert.equal(result.error?.kind, "exception");
	assert.equal(result.error?.message, "deliberate");
});

test("non-JSON completion value fails as invalid-output", async () => {
	const result = await runInWorker(specOf("return () => {}"), CONFIG);
	assert.equal(result.error?.kind, "invalid-output");
});

test("oversized captured logs fail as output-limit", async () => {
	const config = { ...CONFIG, maxOutputBytes: 1024 };
	const result = await runInWorker(specOf(`console.log(${JSON.stringify("x".repeat(4096))}); return 1`), config);
	assert.equal(result.error?.kind, "output-limit");
});

test("oversized completion value fails as output-limit", async () => {
	const config = { ...CONFIG, maxOutputBytes: 1024 };
	const result = await runInWorker(specOf(`return ${JSON.stringify("y".repeat(8192))}`), config);
	assert.equal(result.error?.kind, "output-limit");
});

test("undeclared binding member surfaces inside the program as a TypeError", async () => {
	const program = `
		try {
			await tools.nope({});
			return 'unreached';
		} catch (error) {
			return { name: error.name, message: error.message };
		}
	`;
	const result = await runInWorker(specOf(program), CONFIG);
	assert.deepEqual(result.value, { name: "TypeError", message: "tools.nope is not a function" });
});

test("abort after completion is a no-op", async () => {
	const run = startRun(specOf("return 7"), CONFIG);
	const result = await run.result;
	run.abort("late");
	assert.deepEqual(result, { logs: [], value: 7 });
	assert.deepEqual(await run.result, { logs: [], value: 7 });
	await run.finished;
});

test("clampTimeoutMs defaults, caps and validates", () => {
	assert.equal(clampTimeoutMs(undefined, CONFIG), 5000);
	assert.equal(clampTimeoutMs(999999999, CONFIG), 10000);
	assert.equal(clampTimeoutMs(1500, CONFIG), 1500);
	assert.equal(clampTimeoutMs(null, CONFIG), null);
	assert.throws(() => clampTimeoutMs(0, CONFIG));
	assert.throws(() => clampTimeoutMs(-5, CONFIG));
	assert.throws(() => clampTimeoutMs(Number.NaN, CONFIG));
});

test("validateBindings enforces the portable namespace contract", () => {
	assert.throws(() => validateBindings({ program: "return 1", bindings: [{ global: "console", functions: { a: async () => {} } }] }), /invalid binding global/);
	assert.throws(() => validateBindings({ program: "return 1", bindings: [{ global: "$tools", functions: { a: async () => {} } }] }), /invalid binding global/);
	assert.throws(() => validateBindings({ program: "return 1", bindings: [{ global: "tools", functions: { a: 1 } }] }), /must be a function/);
	const valid = { program: "return 1", bindings: makeBindings() };
	assert.doesNotThrow(() => validateBindings(valid));
	assert.throws(() => {
		validateBindings({ program: "return 1", bindings: [...makeBindings(), ...makeBindings()] });
	}, /duplicate binding global/);
	const badMember = {
		program: "return 1",
		bindings: [{ global: "tools", functions: { a: async () => {} }, errorClass: { name: "ToolCallError", memberNameProperty: "message" } }]
	};
	assert.throws(() => validateBindings(badMember), /invalid error member name/);
});

test("jsonViolation flags non-lossless values with a path", () => {
	assert.equal(jsonViolation(null, "v"), null);
	assert.equal(jsonViolation({ a: [1, "x", true, { b: 2 }] }, "v"), null);
	assert.match(jsonViolation(Number.NaN, "v"), /non-finite/);
	assert.match(jsonViolation({ a: { b: undefined } }, "v"), /v\.a\.b: undefined/);
	assert.match(jsonViolation([1, () => {}], "v"), /v\[1\]: function/);
});

test("normalizeConfig fills defaults and rejects invalid fields", () => {
	const config = normalizeConfig({});
	assert.equal(config.timeoutMs, 12e4);
	assert.equal(config.maxTimeoutMs, 6e5);
	assert.equal(config.maxOutputBytes, 1048576);
	assert.equal(config.maxOldGenerationSizeMb, 256);
	const partial = normalizeConfig({ timeoutMs: 30000 });
	assert.equal(partial.timeoutMs, 30000);
	assert.equal(partial.maxOutputBytes, 1048576);
	assert.throws(() => normalizeConfig({ timeoutMs: -1 }), /positive and finite/);
	assert.throws(() => normalizeConfig({ maxOutputBytes: 3 }), /at least 4/);
	assert.throws(() => normalizeConfig({ timeoutMs: 9999999, maxTimeoutMs: 10 }), /must not exceed/);
});

test("worker module rejections surface as worker-exit", async () => {
	const bindings = makeBindings({
		echo: async (args) => ({ isError: false, value: args }),
		boom: async () => ({ isError: true, message: "kaput" })
	});
	const result = await runInWorker({ ...specOf("return 'ok'", bindings), timeoutMs: null }, CONFIG);
	assert.deepEqual(result, { logs: [], value: "ok" });
});

test("service methods run through a Proxy receiver (cordis traceable contract)", async () => {
	const ctx = { effect: () => () => {}, reflect: { provide: () => {} } };
	const runtime = new OhosPtcRuntime(ctx, CONFIG);
	const shadow = new Proxy(runtime, {
		get(target, prop) {
			if (prop === "ctx") return ctx;
			const value = Reflect.get(target, prop, shadow);
			if (typeof value === "function" && prop !== "constructor") {
				return new Proxy(value, { apply: (fn, thisArg, args) => Reflect.apply(fn, shadow, args) });
			}
			return value;
		}
	});
	const resolved = shadow.resolve({ program: "const r = await tools.echo({ hi: 1 }); return r", bindings: makeBindings() });
	assert.equal(resolved.timeoutMs, CONFIG.timeoutMs);
	assert.equal(shadow.timeout.maxMs, CONFIG.maxTimeoutMs);
	const result = await shadow.run(resolved);
	assert.deepEqual(result, { logs: [], value: { hi: 1 } });
	assert.equal(runtime.activeRuns.size, 0);
});
